$(function() {
        const chartData = [];

        window.newChart = () => {
            /**
             * 取得圖表資料
             */
            $('.chart').each(function() {
                const str = $(this).data('chart');
                if (str == undefined) return;
                // html string to json
                let data = str
                    .replace(/&quot;/g, '"')
                    .replace(/&lt;/g, '<')
                    .replace(/&gt;/g, '>')
                    .replace(/&amp;/g, '&')
                    .replace(/&nbsp;/g, ' ')
                    .replace(/&apos;/g, "'")
                data = JSON.parse(data);
                chartData.push({
                    id: $(this).attr('id'),
                    code: `{{CHART.${$(this).data('code')}}}`,
                    title: $(this).data('title'),
                    type: $(this).data('type'),
                    importData: data,
                });
            });

            chartData.forEach((item, index) => {
                item.chart = new ChartPreview(item);
            });
            window.chartIntances = chartData.map(item => item.chart);
        }

        window.destoryChart = () => {
            chartData.forEach((item, index) => {
                item.chart.chart.destroy();
            });
            chartData.splice(0, chartData.length);
            window.chartIntances = [];
        }

        newChart();
    });

$(function() {
        $('.textEditor .numberList, .textEditor .cardList, .textEditor .infoList').each(function() {
            let counts = [];
            const wrap = $(this);
            wrap.find('.num .text').each(function() {
                const num = $(this).text().trim();
                const len = num.length;
                let decimalPlaces = 0;
                if (num.indexOf('.') > -1) {
                    decimalPlaces = 2;
                }
                const options = {
                    separator: ',',
                    decimalPlaces,
                    duration: 2,
                }
                const count = new countUp.CountUp($(this)[0], num, options);
                counts.push(count);
            });

            let isStart = false;
            if ($(document).scrollTop() > wrap.offset().top - $(window).height() / 1.05) {
                if (isStart) return;
                setTimeout(() => {
                    counts.forEach(function(count) {
                        count.start();
                    });
                }, 300);
                isStart = true;
            }
            $(document).on('scroll', function() {
                if ($(document).scrollTop() > wrap.offset().top - $(window).height() / 1.05) {
                    if (isStart) return;
                    setTimeout(() => {
                        counts.forEach(function(count) {
                            count.start();
                        });
                    }, 300);
                    isStart = true;
                }
            });
        });
    })

$(function() {
        const currentSlide = $('.swiper-slide.current').index();
        const startSlide = currentSlide - 1 < 0 ? 0 : currentSlide - 1;

        const num = $('.swiper-slide.classItem').length;
        let itemWidth = 0;
        $('.classLink .classItem').each(function() {
            itemWidth += $(this).outerWidth();
        });
        let containerWidth = $('.classLink').outerWidth();

        const swiper = new Swiper('.swiperClassLink', {
            slidesPerView: 'auto',
            freeMode: {
                enabled: true,
                sticky: true,
            },
            initialSlide: startSlide,
            // loopedSlides: 8,
            // loop: true,
            on: {
                init: function() {
                    if (currentSlide === 0) {
                        $('.classLink').addClass('onLeft');
                    }
                },
            }
        });

        if (itemWidth < containerWidth) {
            $('.classLink').addClass('onRight');
            $('.classLink').addClass('onLeft');
        } else {
            if (currentSlide === 0) {
                $('.esgList').addClass('onLeft');
            }

            if (currentSlide === num - 1) {
                $('.esgList').addClass('onRight');
            }

            swiper.on('slideChangeTransitionEnd', function() {
                if (swiper.isBeginning) return;
                if (swiper.isEnd) return;
                $('.classLink').removeClass('onLeft');
                $('.classLink').removeClass('onRight');
            });

            swiper.on('reachEnd', function() {
                $('.classLink').addClass('onRight');
                $('.classLink').removeClass('onLeft');
            });

            swiper.on('reachBeginning', function() {
                $('.classLink').addClass('onLeft');
                $('.classLink').removeClass('onRight');
            });
        }
    });

