        }
    }

    function handleHeaderShow() {
        $('header').addClass('show');
    }

    function initPageShow() {
        handleBannerShow();
        handleHeaderShow();
    }

    // 監聽載入完成事件
    document.addEventListener('bannerStart', initPageShow);

    // 處理已跳過 loading 的情況
    if (window._bannerShouldStart) {
        initPageShow();
    }

// 檢查瀏覽器是否支援LocalStorage
