        // 顏色點擊切換相簿
        $(document).on('click', '.colorList button', function(){
            let current = $(this);
            let currentMblink = current.data('id');

            // 如果已經是當前選中，就不重複執行
            if(current.hasClass('current')) {
                return false;
            }

            // 防止記憶體洩漏：更新 HTML 前先銷毀舊的 Slick 實例
            try {
                if ($('.albumListMain').hasClass('slick-initialized')) {
                    $('.albumListMain').slick('unslick');
                }
                if ($('.albumListNav').hasClass('slick-initialized')) {
                    $('.albumListNav').slick('unslick');
                }
            } catch(e) {}

            let callBack = function() {
                current.addClass('current');
                current.siblings().removeClass('current');

                // 建立全新實例以獲取最新的 DOM 元素並初始化
                const newAlbumEvent = new albumTriggerObj();
                newAlbumEvent.initial();

                $('.titan').lightGallery({
                    actualSize: false,
                    download: false,
                    hash: false,
                    share: false,
                    // 影片自動撥放設定
                    autoplayFirstVideo: false,
                    tumbnails: false,
                    youtubePlayerParams: {
                        rel: 0,
                        controls: 0
                    },
                });
            }

            homeClassAjax.get('.albumBox', 'products', currentMblink, 3, callBack);
        });

